        foreach (var b in blogs) { b.Name = b.Name.Trim(); }
        // Breaking change 4: EF 9 Cosmos uses patch-based (partial) updates by default,
        // only sending changed properties. Use full-document replace if patch isn't enabled
        // on your Cosmos account, or keep the default if patch is supported.
        context.SaveChanges();

        // Breaking change 5: Raw SQL queries referencing "Discriminator" must be updated
        // OR the discriminator property must be mapped back to "Discriminator" (done above).
        // If the mapping fix above is applied, this query still works as-is:
        //   SELECT * FROM c WHERE c.Discriminator = 'Blog'
        // Without the mapping fix, you'd need:
        //   SELECT * FROM c WHERE c["$type"] = 'Blog'
    }
}

